"""第三批：换件/故障型答案页（购买意图最强）"""
NEW = [
 {'slug': 'replace-worn-router-bit-set', 'q': 'My router bits are burning the wood — replace the set or just the bit?', 'a': 'If more than two profiles burn, replace the set. Burning is usually wear plus too high an rpm, not a single bad bit.', 'body': '<table><tr><th>Symptom</th><th>Cause</th><th>Action</th></tr><tr><td>One profile burns</td><td>That bit is dull or has pitch build-up</td><td>Clean it, then replace that bit only</td></tr><tr><td>Several profiles burn</td><td>Set is worn, or rpm too high</td><td>Replace the set; drop rpm by 4,000</td></tr><tr><td>Burn marks plus chatter</td><td>Feed too slow, bit slipping</td><td>Check collet, increase feed</td></tr></table><p><b>Wear signs:</b> the cutting edge reflects light, carbide looks dull grey instead of bright, or you need to push harder than a year ago. A 12-piece set used weekly lasts roughly 12-24 months.</p>', 'answer_short': 'Replace the set when more than two profiles burn, when the edge reflects light, or when you have to push harder than before. Cleaning a single bit often fixes a one-profile problem.', 'links': ['RB-12W', 'RB-15W']},
 {'slug': 'broke-a-drill-bit-what-to-buy', 'q': 'I snapped a drill bit mid-hole — what should I replace it with?', 'a': 'Replace with cobalt if the material is stainless or hard steel. Snapping is usually too much pressure, wrong rpm, or a bit that was already dull.', 'body': '<table><tr><th>What happened</th><th>Likely cause</th><th>Buy</th></tr><tr><td>Snapped in stainless</td><td>Too much pressure, no cutting fluid, dull bit</td><td>M35 cobalt, 135° split point</td></tr><tr><td>Snapped in mild steel</td><td>Bit wandered then bent</td><td>HSS or cobalt, centre-punch first</td></tr><tr><td>Tip blued and died</td><td>RPM too high, no coolant</td><td>Cobalt, slower speed</td></tr></table><p><b>Removing the broken piece:</b> a left-hand drill bit or a screw extractor, not a punch. Then deburr the hole before retrying.</p>', 'answer_short': 'Replace with an M35 cobalt bit for stainless or hard steel. Snapping usually means too much pressure or an already-dull bit, so fix the technique as well as the bit.', 'links': ['DB-13M', 'DB-51C']},
 {'slug': 'tap-snapped-in-hole-what-now', 'q': 'I broke a tap inside the hole — how do I get it out and what do I buy next?', 'a': 'Do not force it further. Use a tap extractor or spark-erode it out, then drill oversize and fit a thread insert.', 'body': '<table><tr><th>Step</th><th>Action</th></tr><tr><td>1</td><td>Stop. Back the flutes out with a tap extractor (finger-type) if any of the flutes are exposed</td></tr><tr><td>2</td><td>Apply penetrating oil, work the extractor both directions</td></tr><tr><td>3</td><td>If it will not move, drill it out with a solid carbide drill, then fit a Helicoil-style insert</td></tr><tr><td>4</td><td>Next time: 75% thread drill size, cutting fluid, half-turn forward quarter-turn back</td></tr></table><p><b>Buy next:</b> a carbon-steel set for aluminium and brass, HSS or cobalt for steel. Cheap carbon taps snap in steel.</p>', 'answer_short': 'Use a tap extractor first; if it will not move, drill it out and fit a thread insert. Replace with an HSS or cobalt set for steel — carbon taps snap in steel.', 'links': ['TD-40', 'TD-40T']},
 {'slug': 'hole-saw-dull-replace-or-sharpen', 'q': 'My hole saw is cutting slowly — sharpen or replace?', 'a': 'Bi-metal hole saws cannot be sharpened practically. Replace the saw, and check the arbor and pilot bit first.', 'body': '<table><tr><th>Check</th><th>If bad</th></tr><tr><td>Pilot drill blunt</td><td>Replace the pilot — the saw may be fine</td></tr><tr><td>Teeth flattened or shiny</td><td>Replace the saw</td></tr><tr><td>Wood pitch on teeth</td><td>Clean with oven cleaner, not a grinder</td></tr><tr><td>Burning smell in wood</td><td>RPM too high or feed too light</td></tr></table><p><b>Life:</b> a bi-metal saw gives roughly 30-80 holes in 2 mm sheet steel or 100+ in pine. Cutting masonry with it destroys it in one hole.</p>', 'answer_short': 'Bi-metal hole saws are not practically sharpenable. Replace the saw when the teeth are flattened or shiny; check the pilot bit and arbor first, since those fail more often.', 'links': ['HS-8']},
 {'slug': 'carbide-burr-worn-out', 'q': 'How do I know a carbide burr is worn out, and what replaces it?', 'a': 'When the cut gets slow, the flutes look polished, or it starts smearing instead of cutting. Replace with a fresh single or double cut burr of the same shape code.', 'body': '<table><tr><th>Sign</th><th>Meaning</th></tr><tr><td>Flutes look polished or shiny</td><td>Edge rounded over</td></tr><tr><td>Needs more pressure for the same cut</td><td>Worn</td></tr><tr><td>Smears aluminium instead of cutting</td><td>Built-up edge or worn flutes</td></tr><tr><td>Vibration at speed</td><td>Bent shank — discard</td></tr></table><p><b>Life:</b> a burr run at the right speed in aluminium lasts months; run too fast in stainless it can die in one job. Keep the shape code (A, C, D, F, G, H, L, M, N) and match the cut: single for fast removal, double for finish.</p>', 'answer_short': 'Replace a burr when the flutes look polished, you need more pressure than before, or it smears instead of cutting. Keep the same shape code; single cut removes fast, double cut finishes smoother.', 'links': ['CB-10D', 'CB-10S']},
 {'slug': 'router-bit-collet-slipping', 'q': 'My router bit keeps slipping in the collet — what is wrong?', 'a': 'Usually the wrong shank size, a worn collet, or a dirty bore. An 8 mm bit in a 1/4 in collet will always slip.', 'body': '<table><tr><th>Cause</th><th>Fix</th></tr><tr><td>8 mm bit in 1/4 in collet</td><td>Use the correct collet — the sizes differ by 1.65 mm</td></tr><tr><td>Collet worn or scored</td><td>Replace the collet, not the router</td></tr><tr><td>Sawdust or resin in the bore</td><td>Clean with a dry cloth, no oil</td></tr><tr><td>Bit not seated fully</td><td>Insert at least 3/4 of the shank length</td></tr></table><p><b>Safety:</b> a slipping bit can climb out of the cut and throw. Stop and fix it; do not tighten harder.</p>', 'answer_short': 'Slipping means the wrong shank size, a worn collet, or a dirty bore. An 8 mm bit in a 1/4 in collet always slips — the sizes differ by 1.65 mm.', 'links': ['RB-12Z8', 'RB-12W']},
]